  `result` varchar(50) NOT NULL DEFAULT 'fail' COMMENT '返工结果：pass/fail/partial_pass',
  `closed_at` datetime DEFAULT NULL COMMENT '关闭时间',
  `remark` text COMMENT '补充说明',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人ID',
