  `deleted_by` bigint unsigned DEFAULT NULL COMMENT '删除人ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rework_records_no` (`rework_no`),
  KEY `idx_rework_records_source_inspection_id` (`source_inspection_id`),
  KEY `idx_rework_records_recheck_inspection_id` (`recheck_inspection_id`),
  KEY `idx_rework_records_handler_id` (`handler_id`),
  KEY `idx_rework_records_status` (`status`),
  KEY `idx_rework_records_is_deleted` (`is_deleted`),
  KEY `fk_rework_records_created_by` (`created_by`),
  KEY `fk_rework_records_updated_by` (`updated_by`),
  KEY `fk_rework_records_deleted_by` (`deleted_by`),
  CONSTRAINT `fk_rework_records_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rework_records_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rework_records_handler_id` FOREIGN KEY (`handler_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rework_records_recheck_inspection_id` FOREIGN KEY (`recheck_inspection_id`) REFERENCES `inspection_records` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_rework_records_source_inspection_id` FOREIGN KEY (`source_inspection_id`) REFERENCES `inspection_records` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_rework_records_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_rework_records_result` CHECK ((`result` in (_utf8mb4'pass',_utf8mb4'fail',_utf8mb4'partial_pass'))),
  CONSTRAINT `chk_rework_records_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'doing',_utf8mb4'wait_recheck',_utf8mb4'completed',_utf8mb4'closed')))
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='检验问题返工闭环记录表';
